     8	import {waitForIdle} from '@libs/Network/SequentialQueue';
     9	import * as App from '@userActions/App';
    10	import CONST from '@src/CONST';
    11	import SCREENS from '@src/SCREENS';
    12	import SignInPage from './SignInPage';
    13	import type {SignInPageRef} from './SignInPage';
    14	
    15	function SignInModal() {
    16	    const theme = useTheme();
    17	    const StyleUtils = useStyleUtils();
    18	    const siginPageRef = useRef<SignInPageRef | null>(null);
    19	    const session = useSession();
    20	
    21	    useEffect(() => {
    22	        const isAnonymousUser = session?.authTokenType === CONST.AUTH_TOKEN_TYPES.ANONYMOUS;
    23	        if (!isAnonymousUser) {
    24	            // Signing in RHP is only for anonymous users
    25	            Navigation.isNavigationReady().then(() => {
    26	                Navigation.dismissModal();
    27	            });
    28	
    29	            // To prevent deadlock when OpenReport and OpenApp overlap, wait for the queue to be idle before calling openApp.
    30	            // This ensures that any communication gaps between the client and server during OpenReport processing do not cause the queue to pause,
    31	            // which would prevent us from processing or clearing the queue.
    32	            waitForIdle().then(() => {
    33	                App.openApp();
    34	            });
    35	        }
    36	    }, [session?.authTokenType]);
    37	
    38	    return (
    39	        <ScreenWrapper
    40	            style={[StyleUtils.getBackgroundColorStyle(theme.PAGE_THEMES[SCREENS.RIGHT_MODAL.SIGN_IN].backgroundColor)]}
    41	            includeSafeAreaPaddingBottom={false}
    42	            shouldEnableMaxHeight
    43	            shouldShowOfflineIndicator={false}
    44	            testID={SignInModal.displayName}
    45	        >
    46	            <HeaderWithBackButton
    47	                onBackButtonPress={() => {
    48	                    if (!siginPageRef.current) {
    49	                        Navigation.goBack();
    50	                        return;
    51	                    }
    52	                    siginPageRef.current?.navigateBack();
    53	                }}
    54	            />
    55	            <SignInPage
    56	                shouldEnableMaxHeight={false}
    57	                ref={siginPageRef}
    58	            />
    59	        </ScreenWrapper>
    60	    );
    61	}
    62	
    63	SignInModal.displayName = 'SignInModal';
    64	
    65	export default SignInModal;
